/**
  ******************************************************************************
  * @file    page_web.h
  * @brief   Page web servie PAR LA CARTE (port 80) : tableau de bord meteo en
  *          direct, sans Internet ni Cloud. Autonome : aucun fichier externe
  *          (pas de CDN, polices systeme, graphiques en SVG dessines en JS).
  *          Les donnees viennent de GET /api (JSON) toutes les 2 s.
  * @author  Aris Trache - ETRS923, USMB Master ESET
  ******************************************************************************
  */
#ifndef PAGE_WEB_H
#define PAGE_WEB_H

static const char PAGE_WEB[] =
"<!DOCTYPE html><html lang=fr><head><meta charset=utf-8>"
"<meta name=viewport content='width=device-width,initial-scale=1'>"
"<title>IA M\xC3\xA9t\xC3\xA9o Edge - en direct de la carte</title><style>"
":root{--fond:#0F1B2D;--carte:#16263d;--txt:#F3F0E8;--dim:#8fa3bd;--amb:#F2A33A;--teal:#2E9C8F;--bleu:#4C8DF6;--rouge:#E5484D}"
"*{box-sizing:border-box}body{margin:0;background:var(--fond);color:var(--txt);font:16px system-ui,Segoe UI,Arial,sans-serif}"
"main{max-width:1100px;margin:auto;padding:24px}"
"header{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}"
"h1{font-size:22px;margin:0;letter-spacing:.5px}h1 b{color:var(--amb)}"
".pill{padding:6px 14px;border-radius:99px;font-weight:600;font-size:14px;background:var(--carte)}"
".ok{color:#7ee2b8}.ko{color:#ffb4b4;background:#3b1d24}"
".grille{display:grid;grid-template-columns:1.3fr 1fr;gap:18px;margin-top:20px}"
"@media(max-width:800px){.grille{grid-template-columns:1fr}}"
".bloc{background:var(--carte);border-radius:16px;padding:20px}"
".kick{color:var(--dim);font-size:12px;text-transform:uppercase;letter-spacing:1.5px;margin:0 0 8px}"
"#classe{font-size:46px;font-weight:800;margin:4px 0 2px}#icone{font-size:64px;float:right}"
".barre{display:flex;align-items:center;gap:10px;margin:10px 0}.barre span{width:130px;color:var(--dim)}"
".jauge{flex:1;height:14px;background:#0b1422;border-radius:8px;overflow:hidden}"
".jauge i{display:block;height:100%;border-radius:8px;transition:width .6s}"
".mes{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}"
".val{font-size:30px;font-weight:700}.u{color:var(--dim);font-size:14px}"
".perf{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;text-align:center}"
"svg text{fill:var(--dim);font-size:12px;font-family:system-ui,Arial}"
".tip{position:absolute;display:none;background:#0b1422;border:1px solid #26384f;border-radius:10px;padding:8px 12px;font-size:13px;line-height:1.5;pointer-events:none;white-space:nowrap;box-shadow:0 6px 20px #0008}"
".prev{margin-top:14px;padding:12px 14px;border-radius:12px;background:#0b1422;border-left:4px solid var(--teal)}"
".perf div{background:#0b1422;border-radius:12px;padding:12px 6px}.perf .val{font-size:22px}"
"svg{width:100%;display:block;cursor:crosshair}"
"#alerte{display:none;background:var(--amb);color:#1a1205;font-weight:700;border-radius:12px;padding:10px 14px;margin-top:12px}"
"footer{color:var(--dim);font-size:13px;margin-top:18px;text-align:center}"
"</style></head><body><main>"
"<header><h1>IA M\xC3\xA9t\xC3\xA9o <b>Edge</b> \xC2\xB7 STM32N6</h1>"
"<div><span id=net class=pill>...</span> <span id=lien class=pill>carte</span></div></header>"
"<div class=grille><div class=bloc><p class=kick>Pr\xC3\xA9" "diction de l'IA, calcul\xC3\xA9" "e sur la puce</p>"
"<div id=icone>\xE2\x9B\x85</div><div id=classe>...</div><div class=u id=sous></div>"
"<div class=barre><span>D\xC3\xA9gag\xC3\xA9</span><div class=jauge><i id=b0 style='background:var(--amb)'></i></div><b id=p0></b></div>"
"<div class=barre><span>Nuageux-Couvert</span><div class=jauge><i id=b1 style='background:var(--dim)'></i></div><b id=p1></b></div>"
"<div class=barre><span>Pr\xC3\xA9" "cipitations</span><div class=jauge><i id=b2 style='background:var(--bleu)'></i></div><b id=p2></b></div>"
"<div class=prev><span class=kick style='margin:0'>Pr\xC3\xA9vision dans 3 h (2\xE1\xB5\x89 IA)</span><div><span id=i3 style='font-size:28px'>\xE2\x8F\xB3</span> <b id=c3 style='font-size:24px'>\xE2\x80\xA6</b><span id=q3 class=u></span></div></div>"
"<div id=alerte>\xF0\x9F\x92\xA8 Humidit\xC3\xA9 en forte hausse : l'IA r\xC3\xA9" "agit en direct</div></div>"
"<div class=bloc><p class=kick>Capteurs (X-NUCLEO-IKS4A1)</p><div class=mes>"
"<div><div class=val id=T>-</div><div class=u>\xC2\xB0" "C</div></div>"
"<div><div class=val id=H>-</div><div class=u>% humidit\xC3\xA9</div></div>"
"<div><div class=val id=P>-</div><div class=u>hPa (mer)</div></div></div>"
"<p class=kick style='margin-top:18px'>Edge \xE2\x86\x94 Cloud</p><div id=cloud class=u>-</div></div></div>"
"<div class=grille><div class=bloc><p class=kick>Humidit\xC3\xA9 (bleu) et probabilit\xC3\xA9 de pluie (orange), sur tout l\x27historique</p>"
"<div style='position:relative'><svg id=g style='height:210px'></svg><div id=g_tip class=tip></div></div></div>"
"<div class=bloc><p class=kick>Temps d'une pr\xC3\xA9" "diction, mesur\xC3\xA9 sur la carte</p><div class=perf>"
"<div><div class=val id=f0>-</div><div class=u>\xC2\xB5s float32<br>sans caches</div></div>"
"<div><div class=val id=f1>-</div><div class=u>\xC2\xB5s float32</div></div>"
"<div><div class=val id=f2 style='color:var(--amb)'>-</div><div class=u>\xC2\xB5s int8<br>Helium</div></div>"
"<div><div class=val id=f3>-</div><div class=u>\xC2\xB5s NPU</div></div></div>"
"<p class=u id=stats style='margin-top:14px'></p></div></div>"
"<div class=bloc style='margin-top:18px'><p class=kick>Temp\xC3\xA9rature en continu <span id=dur></span></p>"
"<div style='position:relative'><svg id=gt style='height:270px'></svg><div id=gt_tip class=tip></div></div></div>"
"<footer>Page servie par la carte elle-m\xC3\xAAme (LwIP + FreeRTOS), sans Internet. Aris Trache \xC2\xB7 USMB Master ESET</footer>"
"</main><script>"
"var N=['D\xC3\xA9gag\xC3\xA9','Nuageux-Couvert','Pr\xC3\xA9" "cipitations'],I=['\xE2\x98\x80\xEF\xB8\x8F','\xE2\x98\x81\xEF\xB8\x8F','\xF0\x9F\x8C\xA7\xEF\xB8\x8F'];"
"var A=null,MAX=30000,n0=-1,ch0=0;"
"function $(i){return document.getElementById(i)}"
"function f(v,d){return v.toFixed(d).replace('.',',')}"
"function hm(s,span){var d=new Date(s*1000),o={hour:'2-digit',minute:'2-digit'};return span>86400?d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('fr-FR',o):d.toLocaleTimeString('fr-FR',o)}"
"function duree(s){return s<120?s+' s':s<7200?Math.floor(s/60)+' min':Math.floor(s/3600)+' h '+Math.floor(s%3600/60)+' min'}"
"function graphe(id,t,S,uG,uD){var g=$(id),W=g.clientWidth||600,H=g.clientHeight||200,L=50,R=uD?44:14,T=22,B=26,w=W-L-R,h=H-T-B;g.setAttribute('viewBox','0 0 '+W+' '+H);"
"var a=t[0],b=t[t.length-1];if(b<=a)b=a+1;function X(x){return L+(x-a)*w/(b-a)}function Y(q,v){return T+h-(v-q.mi)*h/(q.ma-q.mi)}"
"var s='',i,y;for(i=0;i<=4;i++){y=T+h-i*h/4;s+=\"<line x1=\"+L+\" x2=\"+(L+w)+\" y1=\"+y+\" y2=\"+y+\" stroke='#26384f'/><text x=\"+(L-6)+\" y=\"+(y+4)+\" text-anchor=end>\"+f(S[0].mi+(S[0].ma-S[0].mi)*i/4,1)+\"</text>\";"
"if(uD)s+=\"<text x=\"+(L+w+6)+\" y=\"+(y+4)+\">\"+Math.round(S[1].mi+(S[1].ma-S[1].mi)*i/4)+\"</text>\"}"
"for(i=0;i<=4;i++){var x=L+i*w/4;s+=\"<line x1=\"+x+\" x2=\"+x+\" y1=\"+(T+h)+\" y2=\"+(T+h+4)+\" stroke='#8fa3bd'/><text x=\"+x+\" y=\"+(H-6)+\" text-anchor=\"+(i==0?'start':i==4?'end':'middle')+\">\"+hm(a+(b-a)*i/4,b-a)+\"</text>\"}"
"s+=\"<text x=\"+(L-6)+\" y=12 text-anchor=end>\"+uG+\"</text>\";if(uD)s+=\"<text x=\"+(W-2)+\" y=12 text-anchor=end>\"+uD+\"</text>\";"
"S.forEach(function(q){var p='';for(var k=0;k<t.length;k++)p+=(k?'L':'M')+X(t[k]).toFixed(1)+' '+Y(q,q.v[k]).toFixed(1);s+=\"<path d='\"+p+\"' fill=none stroke='\"+q.c+\"' stroke-width=2.5 stroke-linejoin=round />\"});"
"g.innerHTML=s+\"<g id=\"+id+\"_m></g>\";"
"g.onmousemove=function(e){g._e=e;var r=g.getBoundingClientRect(),tt=a+(e.clientX-r.left-L)*(b-a)/w,k=0,best=1e18;for(var j=0;j<t.length;j++){var d=Math.abs(t[j]-tt);if(d<best){best=d;k=j}}"
"var x=X(t[k]),m=\"<line x1=\"+x+\" x2=\"+x+\" y1=\"+T+\" y2=\"+(T+h)+\" stroke='#8fa3bd' stroke-dasharray='3 3'/>\";"
"S.forEach(function(q){m+=\"<circle cx=\"+x+\" cy=\"+Y(q,q.v[k])+\" r=5 fill='\"+q.c+\"' stroke='#F3F0E8' stroke-width=2 />\"});$(id+'_m').innerHTML=m;"
"var tip=$(id+'_tip');tip.style.display='block';tip.innerHTML=new Date(t[k]*1000).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'})+S.map(function(q){return \"<br><b style='color:\"+q.c+\"'>\"+q.n+' : '+f(q.v[k],1)+' '+q.u+'</b>'}).join('');"
"var px=x+14;if(px>W-170)px=x-174;tip.style.left=px+'px';tip.style.top=T+'px'};"
"g.onmouseleave=function(){g._e=null;$(id+'_m').innerHTML='';$(id+'_tip').style.display='none'};if(g._e)g.onmousemove(g._e)}"
"function dessiner(){if(!A||A.t.length<2)return;var k=A.t.length;"
"var h=A.H,m=Math.min.apply(0,h.concat([30])),M=Math.max.apply(0,h.concat([70]));"
"graphe('g',A.t,[{v:h,c:'#4C8DF6',mi:m-2,ma:M+2,n:'Humidit\xC3\xA9',u:'%'},{v:A.P,c:'#F2A33A',mi:0,ma:100,n:'Pluie (IA)',u:'%'}],'% hum.','% pluie');"
"var t=A.T,mi=Math.min.apply(0,t),ma=Math.max.apply(0,t);if(ma-mi<1){mi-=.5;ma+=.5}"
"graphe('gt',A.t,[{v:t,c:'#F2A33A',mi:mi,ma:ma,n:'Temp\xC3\xA9rature',u:'\xC2\xB0" "C'}],'\xC2\xB0" "C');"
"$('dur').textContent='('+duree(Math.round(A.t[k-1]-A.t[0]))+', '+k+' points, historique '+(A.src=='Cloud'?'ThingSpeak':'de la carte')+')';"
"var e=k>5?h[k-1]-h[k-6]:0;$('alerte').style.display=e>8?'block':'none'}"
"function vide(){return{t:[],T:[],H:[],P:[]}}"
"function histoCarte(up){fetch('/histo',{cache:'no-store'}).then(function(r){return r.json()}).then(function(h){var now=Date.now()/1000;A=vide();"
"for(var i=0;i<h.t.length;i++){A.t.push(now-(up-h.t[i]));A.T.push(h.T[i]);A.H.push(h.H[i]);A.P.push(h.P[i])}A.src='carte';dessiner()}).catch(function(){A=vide()})}"
"function charger(d){if(!d.ch){histoCarte(d.up);return}"
"fetch('https://api.thingspeak.com/channels/'+d.ch+'/feeds.json?results=8000'+(d.rk?'&api_key='+d.rk:'')).then(function(r){return r.json()}).then(function(j){"
"var e=j.feeds.map(function(x){return[Date.parse(x.created_at)/1000,parseFloat(x.field1),parseFloat(x.field2),parseFloat(x.field5)]}).filter(function(x){return!isNaN(x[0])&&x[0]<Date.now()/1000+120&&!isNaN(x[1])&&!isNaN(x[2])});"
"e.sort(function(a,b){return a[0]-b[0]});A=vide();e.forEach(function(x){A.t.push(x[0]);A.T.push(x[1]);A.H.push(x[2]);A.P.push(isNaN(x[3])?0:x[3])});"
"A.src='Cloud';if(A.t.length<2)histoCarte(d.up);else dessiner()}).catch(function(){histoCarte(d.up)})}"
"function maj(){fetch('/api',{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){"
"$('lien').textContent='carte en ligne \xC2\xB7 '+d.n+' pr\xC3\xA9" "dictions';$('lien').className='pill ok';"
"$('classe').textContent=N[d.c];$('icone').textContent=I[d.c];"
"$('sous').textContent='m\xC3\xAAme r\xC3\xA9ponse sur le CPU int8 et sur le NPU';"
"for(var i=0;i<3;i++){$('b'+i).style.width=d.pr[i]+'%';$('p'+i).textContent=d.pr[i]+'%'}"
"if(d.p3){$('i3').textContent=I[d.c3];$('c3').textContent=N[d.c3];$('q3').textContent=' \xC2\xB7 '+d.p3[d.c3]+' % \xC2\xB7 pluie '+d.p3[2]+' %'}"
"$('T').textContent=f(d.T,1);$('H').textContent=f(d.H,1);$('P').textContent=f(d.P,1);"
"var n=$('net');if(d.net){n.textContent='Internet OK';n.className='pill ok'}else{n.textContent='Internet coup\xC3\xA9 \xC2\xB7 '+d.att+' mesures gard\xC3\xA9" "es';n.className='pill ko'}"
"$('cloud').innerHTML=d.cl<0?'En attente de la 1re r\xC3\xA9ponse de l\\'IA Cloud (MATLAB, toutes les 10 min)':"
"'IA Cloud : <b>'+N[d.cl]+'</b> \xC2\xB7 IA carte : <b>'+N[d.c]+'</b> \xE2\x86\x92 '+(d.cl==d.c?'<b class=ok>D\\'ACCORD</b>':'<b>d\xC3\xA9saccord</b>');"
"if(!d.net)$('cloud').innerHTML+='<br>Sans Internet, l\\'IA embarqu\xC3\xA9" "e continue : '+d.att+' mesures attendent le retour du r\xC3\xA9seau.';"
"$('f0').textContent=f(d.off,1);$('f1').textContent=f(d.f32,1);$('f2').textContent=f(d.s8,1);$('f3').textContent=d.npu>0?f(d.npu,1):'-';"
"$('stats').textContent='Allum\xC3\xA9" "e depuis '+duree(d.up)+' \xC2\xB7 '+d.ts+' envois Cloud \xC2\xB7 '+d.rat+' mesures rattrap\xC3\xA9" "es apr\xC3\xA8s coupure';"
"if(!A&&!ch0){ch0=1;charger(d)}if(A&&d.n!=n0){n0=d.n;A.t.push(Date.now()/1000);A.T.push(d.T);A.H.push(d.H);A.P.push(d.pr[2]);"
"if(A.t.length>MAX){A.t.shift();A.T.shift();A.H.shift();A.P.shift()}dessiner()}"
"}).catch(function(){$('lien').textContent='carte injoignable';$('lien').className='pill ko'})}"
"maj();setInterval(maj,2000);"
"</script></body></html>";

#endif /* PAGE_WEB_H */
